"""Create additional historical terms with concrete examples and lesson links."""
import json
from pathlib import Path
terms=[]
def add(id,title,definition,example,sources,lessonIds):
 terms.append(dict(id=id,title=title,definition=definition,example=example,sources=sources.split(),lessonIds=lessonIds.split()))
add('археология','Археология','Наука, которая изучает прошлое по материальным следам человеческой жизни: остаткам построек, орудиям, погребениям, мусору и изменениям ландшафта. Значение находки зависит не только от её вида, но и от того, где и рядом с чем она обнаружена.','Стоянка Сунгирь рассказывает о людях каменного века через погребения, украшения и орудия; письменного рассказа самих этих людей не сохранилось.','ar-sungir ar-sungir-dates','01-003 01-004')
add('стратиграфия','Стратиграфия','Изучение последовательности слоёв, образовавшихся в земле. Если слои не перемешаны, нижний обычно отложился раньше верхнего. Это позволяет установить относительную последовательность событий, но само по себе не даёт точного календарного года.','При раскопках города пол более позднего дома может перекрывать остатки сгоревшего раннего здания. Перекоп или поздняя яма способны нарушить порядок слоёв.','ar-dates ar-sungir-dates','01-004 01-013')
add('радиоуглеродный анализ','Радиоуглеродный анализ','Способ оценить возраст органического материала по содержанию радиоактивного углерода-14, который после смерти организма постепенно распадается. Результат сопоставляют с калибровочной шкалой и получают интервал вероятных дат. Метод датирует образец, а его связь с событием надо обосновать.','Уголь из очага помогает датировать деятельность людей на стоянке, если он действительно относится к этому очагу. Загрязнение образца или использование старого дерева может исказить вывод о времени поселения.','ar-dates ar-sungir-dates','01-013')
add('этногенез','Этногенез','Длительный процесс формирования общности людей, которую начинают отличать по языку, самоназванию, культуре и представлениям об общем происхождении. Такие общности меняются и включают людей разного происхождения. Археологическая культура, язык и современная нация не являются одним и тем же.','Расселение славян изучают вместе с языковыми и археологическими данными; похожая керамика сама по себе не доказывает, как называли себя все её изготовители.','ar-slav-sedov ar-prague','01-008 01-009 01-016')
add('язычество','Язычество','Общее название разных религиозных представлений и практик вне христианства и других религий, с позиции которых используется это слово. Для восточных славян речь идёт о почитании божеств, предков и природных сил. Единой неизменной «языческой церкви» у них не было.','Летопись рассказывает о кумирах, установленных Владимиром в Киеве до крещения. Автор-христианин оценивал старые верования как ложные, что нужно учитывать при чтении.','ar-pvl-full early','01-010 02-009')
add('князь','Князь','Правитель, чьи полномочия в разные эпохи сочетали военное руководство, суд и получение доходов. В Руси князья принадлежали к правящей династии, но их реальная власть зависела от дружины, договоров, местной знати и горожан. «Князь» не означает одинаковую должность во всех землях и столетиях.','Новгород мог приглашать князя для военной и судебной службы, ограничивая его соглашением; положение великого князя владимирского строилось иначе.','med-novgorod med-rus','02-001 02-012 03-003')
add('вече','Вече','Собрание горожан, участвовавшее в решении общественных дел. В Новгороде и Пскове оно могло влиять на выбор должностных лиц, отношения с князем и внешнюю политику. Порядок участия и влияние разных групп менялись; считать вече современным парламентом со всеобщим равным голосованием нельзя.','Новгородская летопись рассказывает об изгнании князя Всеволода в 1136 году. Это показывает возможности городской общины, но не доказывает равенства всех жителей.','med-novgorod med-veche','03-003 04-018')
add('бояре','Бояре','Влиятельная верхушка общества, связанная с землевладением, службой князю и управлением. Состав и значение боярства менялись. Боярин в московской иерархии был также высоким служебным чином; его положение нельзя объяснять только богатством или древностью рода.','В Новгороде боярские семьи влияли на городское управление, а в Москве бояре участвовали в совете при государе и выполняли военные и административные поручения.','med-veche muscovy','02-012 03-003 04-012')
add('вотчина','Вотчина','Земельное владение, которым владелец распоряжался на наследственном основании. Его можно было передавать потомкам, а в допустимых законом пределах — продавать или дарить. Конкретные ограничения зависели от времени и происхождения земли. Владение землёй не означало одинаковой власти над всеми жившими на ней людьми.','Боярин или монастырь мог иметь вотчину с деревнями и получать с них доход. В Московском государстве вотчинное землевладение сосуществовало с поместным.','med-growth muscovy','04-009 04-012 05-023')
add('поместье','Поместье','В Московском государстве — земельное владение, предоставлявшееся служилому человеку для обеспечения службы государю. Первоначально распоряжение такой землёй было ограничено сильнее, чем вотчиной. Со временем различия между двумя формами владения уменьшались.','Помещик получал доход с предоставленных земель и должен был являться на военную службу с положенным вооружением. Это связывало обеспечение войска с трудом сельского населения.','med-growth muscovy','04-009 05-003 05-019')
add('вира','Вира','Денежное взыскание в пользу князя за убийство, предусмотренное Русской Правдой. Размер и порядок выплаты зависели от правового положения погибшего и обстоятельств. Вира отличается от возмещения родственникам и от современной системы уголовного наказания.','Русская Правда устанавливает виры за убийство разных категорий людей. Сравнение сумм показывает, что право различало их общественное положение.','ar-rp-primary ar-nlr-rp','02-011 02-012')
add('смерд','Смерд','Название категории населения в древнерусских источниках, обычно связанной с сельским хозяйством и отношениями зависимости от князя. Точный правовой статус смердов и его изменение обсуждаются: разные тексты не позволяют считать всех смердов одинаково свободными крестьянами или одинаково бесправными рабами.','В Русской Правде упоминание смерда встречается при обсуждении имущества и ответственности. Сначала нужно проверить редакцию и контекст статьи, а затем делать вывод о его положении.','ar-rp-primary ar-nlr-law','02-012 02-021')
add('закуп','Закуп','Человек, получивший «купу» — заём или хозяйственное предоставление — и обязанный отработкой кредитору. По Русской Правде он имел определённую правовую защиту, но его возможности были ограничены долгом. При некоторых нарушениях мог утратить свой статус и оказаться в более тяжёлой зависимости.','Правда регулирует ответственность закупа за имущество хозяина и запрещает произвольное обращение с ним. Это пример того, как долг менял положение человека, не превращая сразу любого должника в холопа.','ar-rp-primary ar-nlr-rp','02-011 02-021')
add('холоп','Холоп','В древнерусском и московском обществе — человек в наиболее тяжёлой личной зависимости от владельца. Источниками холопства могли быть плен, рождение в зависимой семье и установленные правом сделки или обстоятельства. Положение менялось со временем; холопство не совпадает во всех деталях с позднейшим крепостным правом.','Русская Правда перечисляет условия поступления в полное холопство. В Московском государстве существовали также кабальные формы зависимости, связанные с обязательством службы по документу.','ar-rp-primary muscovy','02-021 05-019')
add('удел','Удел','Часть династических владений, переданная определённому князю или ветви княжеской семьи. Удел включал территорию, доходы и политические права, а его границы и самостоятельность зависели от договоров и соотношения сил. Слово не означает просто современный административный район.','Передача городов сыновьям великого князя создавала собственные центры власти. В XV веке отношения московского правителя с удельными родственниками стали причиной длительной усобицы.','med-emergence ref-moscow-civilwar','02-018 04-005')
add('посадник','Посадник','Должностное лицо, участвовавшее в управлении городом. В ранний период посадник мог быть представителем князя; в Новгороде его должность стала важной частью городского самоуправления и борьбы боярских групп. Полномочия и способ замещения должности менялись.','Новгородский посадник участвовал в суде и отношениях с приглашённым князем. Наличие выборной должности не означает, что все жители имели одинаковое влияние на её получение.','med-novgorod med-veche','03-003 04-018')
add('орда','Орда','Слово, которое могло обозначать ставку правителя, его окружение и политическое объединение. В истории русских земель «Орда» часто означает государство потомков Джучи, принятое в историографии называть Золотой Ордой. Это было сложное государство с городами, торговлей и разными народами, а не только кочевое войско.','Русские князья ездили к ханам Орды за подтверждением власти. Их обязательства были частью политических отношений с государством, возникшим в западной части Монгольской империи.','med-mongol-expansion med-mongol-method','03-006 03-010 03-019')
add('баскак','Баскак','Представитель монгольской власти, связанный с надзором за подвластным населением, учётом и обеспечением сбора дани. Его функции и распространение института различались по землям и времени. Нельзя считать, что баскаки неизменно и повсюду лично собирали каждую выплату.','В Северо-Восточной Руси отношения князей, ханских представителей и местных сборщиков менялись. Позднее значительная часть ответственности за выплаты лежала на самих русских князьях.','med-mongol-method mongol','03-010 03-017')
add('ясак','Ясак','В истории освоения Сибири — установленная властью дань с части местного населения, часто пушниной. Размер, способы сбора и освобождения от платежа зависели от времени и местности. Ясак был инструментом подчинения и получения дохода; его нельзя смешивать с монгольской Ясой — названием правовых установлений.','Сибирские общины передавали государевым сборщикам меха. Споры о размере дани, насилие сборщиков и конкуренция за ресурсы могли вызывать сопротивление.','muscovy cambridge1','05-008 07-029')
add('кормление','Кормление','Порядок обеспечения местного должностного лица доходами и сборами с управляемой территории. Наместник или волостель получал установленное содержание от населения вместо единого современного жалованья. Граница между разрешённым сбором и злоупотреблением была важным предметом конфликтов.','В ходе реформ середины XVI века кормления отменяли и перестраивали местное управление. Это не означало мгновенного исчезновения поборов и произвола.','muscovy em-sudebnik','04-012 05-003')
add('местничество','Местничество','Порядок распределения служебных назначений с учётом знатности рода и прежней службы самого человека и его родственников. Спор шёл о том, кому допустимо подчиняться без ущерба семейной чести. Этот порядок ограничивал свободу назначений государя и порождал конфликты.','Военачальники могли спорить о старшинстве при назначении в полки. В 1682 году местничество отменили, но это не устранило неформального значения происхождения и связей.','muscovy cambridge1','04-012 05-003 05-023')
add('юрьев день','Юрьев день','В контексте Судебника 1497 года — ограниченный срок осеннего перехода крестьянина от одного землевладельца к другому: неделя до и неделя после дня святого Георгия. Для перехода требовалась выплата установленного пожилого. Это право было условным и не равно свободе передвижения современного гражданина.','Судебник задавал единый временной коридор перехода. Позднейшие запреты и сыск беглых сокращали возможности ухода и стали частью закрепощения.','med-law1497 em-law1649','04-010 04-019 05-019')
add('барщина','Барщина','Обязанность зависимого крестьянина трудиться на хозяйство землевладельца своим трудом, а нередко и со своим инвентарём. Это могли быть полевые, строительные и другие работы. Размер повинности менялся; барщина существовала рядом с натуральными и денежными платежами.','Крестьянин несколько дней обрабатывал господское поле, а оставшееся время — свой надел. Павловский манифест 1797 года затрагивал распределение труда, но не отменял зависимости.','cambridge2 ref-paul fe-paul-law','05-019 06-030 07-014')
add('оброк','Оброк','Повинность в виде передачи владельцу продуктов, изделий или денег. Её отличают от барщины, при которой отдавали рабочее время. Денежный оброк мог побуждать крестьянина заниматься промыслом или торговлей, но сам по себе не делал его лично свободным.','Крепостной мог зарабатывать в городе и платить помещику деньги. Возможность отлучиться и размер платежа зависели от правового положения и отношений с владельцем.','cambridge2 reforms','05-019 06-030 07-023')
add('приказ','Приказ как учреждение','Центральное учреждение Московского государства, ведавшее определённым кругом дел, территорией или группой служилых людей. Приказы занимались дипломатией, войском, налогами и судом; их обязанности могли пересекаться. Это историческое название учреждения, а не только распоряжение начальника.','Посольский приказ вёл дипломатические дела, а Разрядный — значительную часть вопросов военной службы. Пётр I постепенно перестраивал эту систему, создавая новые органы.','muscovy imperial','04-012 05-023 06-009')
add('сословие','Сословие','Большая общественная группа с закреплёнными законом правами, обязанностями и особенностями службы или налогообложения. Принадлежность часто передавалась по рождению, хотя переходы были возможны. Сословие отличается от группы по размеру дохода: богатый купец и бедный дворянин могли иметь разные юридические права.','В Российской империи дворяне, купцы, мещане и крестьяне несли разные повинности. Сословные различия влияли на образование, службу и суд.','cambridge2 reforms','05-023 06-011 07-023')
add('мануфактура','Мануфактура','Производство, где труд многих работников разделён на отдельные операции, но основная работа ещё выполняется ручными инструментами. Разделение операций повышало выпуск продукции. Работники могли быть наёмными, зависимыми или сочетать разные формы занятости; мануфактура не обязательно означала свободный труд.','Петровские суконные и металлургические предприятия обеспечивали армию и государственные заказы. Технологические изменения могли сочетаться с принуждением работников.','imperial cambridge2','06-008 07-017')
add('рекрутская повинность','Рекрутская повинность','Порядок пополнения регулярной армии, при котором общины и другие податные группы должны были предоставлять установленное число людей. Служба была длительной, а выбор рекрута тяжело затрагивал семью и хозяйство. Правила и сроки службы менялись.','При Петре I рекрутские наборы стали постоянным механизмом комплектования войска. Всеобщая воинская повинность 1874 года позднее заменила сословный принцип службы.','imperial reforms','06-004 06-025 07-015')
add('синод','Святейший синод','Высшее коллегиальное учреждение управления Русской православной церковью, созданное при Петре I в 1721 году вместо прежнего порядка с патриархом во главе. Его работу контролировала государственная власть, в том числе через обер-прокурора. Это не обычный церковный собор, собираемый для отдельного решения.','Духовный регламент закреплял устройство нового органа. Синодальная система усиливала связь церковного управления с государственной службой.','fe-synod fe-regulation','06-009 06-010')
add('секуляризация','Секуляризация церковных владений','Передача церковного имущества и доходов под светское, обычно государственное, управление. В более широком смысле слово обозначает уменьшение роли религиозных учреждений в общественной жизни, но эти процессы нельзя смешивать автоматически. Отъём монастырских земель не означал запрета религии.','В 1764 году при Екатерине II монастырские земли и значительная часть доходов перешли государству, а бывшие монастырские крестьяне получили иное управление.','cambridge2 ref-catherine','06-017 06-018')
add('протекционизм','Протекционизм','Политика защиты производителей внутри страны от внешней конкуренции с помощью таможенных пошлин, ограничений ввоза, государственных заказов и других мер. Она может поддержать развитие отраслей, но увеличить цены для покупателей и вызвать ответные меры торговых партнёров.','В конце XIX века российские власти защищали часть промышленности пошлинами и поддерживали железнодорожные заказы. Витте сочетал такую защиту с привлечением иностранного капитала.','ir-witte reforms','06-008 07-020 08-002')
add('просвещённый абсолютизм','Просвещённый абсолютизм','Политика монархов XVIII века, которые сохраняли верховную власть, но обосновывали реформы разумом, пользой государства, образованием и упорядоченным законом. Она допускала изменения сверху без передачи населению права определять власть. Слово «просвещённый» описывает программу, а не безусловно положительную оценку.','Екатерина II рассуждала о законах и наказаниях в «Наказе» Уложенной комиссии, одновременно сохраняя самодержавие и крепостную зависимость.','em-nakaz-original ref-catherine','06-017 06-018 06-029')
add('конституция','Конституция','Основной закон, который определяет устройство государства, полномочия органов власти и права людей. Важно различать написанные правила и то, как они действуют: наличие конституционного текста само по себе не гарантирует независимого суда, свободных выборов или исполнения прав.','Конституция России 1993 года закрепила федеративное устройство и разделение властей. Конституции СССР тоже провозглашали права, но практика однопартийной власти ограничивала их осуществление.','mod-constitution-original sov-brezhnev','09-030 10-004')
add('конституционная монархия','Конституционная монархия','Государственный строй, в котором власть монарха ограничена основным законом и полномочиями других учреждений. Ограничения бывают разными: монарх может сохранять большую исполнительную власть либо выполнять преимущественно представительские функции. Это не всегда парламентская система, где правительство зависит от большинства депутатов.','После 1905–1906 годов российский император делил законодательные полномочия с Думой и Государственным советом, но сохранял широкие права. Поэтому степень конституционного ограничения самодержавия остаётся предметом обсуждения.','root-october-archive revolution','08-007 08-023')
add('цензура','Цензура','Контроль власти или уполномоченного учреждения над распространением текстов, изображений и других сообщений. Контроль может предшествовать публикации либо выражаться в запрете и наказании после неё. Цензура ограничивает доступность свидетельств, поэтому отсутствие критики в печати не доказывает отсутствия недовольства.','При Николае I надзор ограничивал печать; в СССР разрешение на публикацию зависело от государственных и партийных механизмов. Самиздат распространяли вне официального разрешения.','ir-nicholas sov-brezhnev ref-solzhenitsyn','07-009 09-008 09-054')
add('национализм','Национализм','Совокупность идей, в которых нация рассматривается как важнейшее политическое сообщество и основание права на власть или государственность. В разные эпохи он мог поддерживать равноправие и освобождение либо оправдывать превосходство и исключение других. Его смысл нужно устанавливать по конкретной программе и действиям.','В империях XIX века национальные движения добивались автономии или независимости, тогда как центральные власти стремились укреплять единство государства. Не всякое требование самостоятельности означало одинаковое отношение к меньшинствам.','ir-nationalities med-lithuania','07-024 08-003')
add('декабристы','Декабристы','Участники тайных обществ, главным образом дворяне и офицеры, выступившие против существующего порядка в декабре 1825 года и начале 1826 года. Их объединяло неприятие крепостничества и неограниченного самодержавия, но проекты устройства страны различались. Это не одна партия с единой согласованной программой.','Северное общество обсуждало конституционную монархию, Южное — республиканский проект Пестеля. Восстание на Сенатской площади не смогло обеспечить поддержку большей части войск.','ir-decembrists reforms','07-008')
add('народничество','Народничество','Направление общественной мысли и движения XIX века, возлагавшее надежды на крестьянство и общину при переходе к более справедливому обществу. Внутри него существовали сторонники просвещения, пропаганды, политической борьбы и революционного насилия. Не всех народников можно считать террористами.','«Хождение в народ» 1870-х годов было попыткой вести пропаганду среди крестьян. Позднее «Народная воля» сделала ставку на борьбу с самодержавием, включая политические убийства.','ir-narodnik reforms','07-010 07-016 07-021')
add('пролетариат','Пролетариат','В марксистской теории — люди, которые не владеют средствами производства в достаточном объёме и живут главным образом продажей своего труда. В историческом описании часто имеется в виду промышленный рабочий класс. Общая форма заработка не означала одинаковых условий жизни или единства политических взглядов.','Фабричные рабочие Петербурга могли поддерживать разные партии, участвовать в стачках или избегать политики. Партийное заявление о защите пролетариата не доказывает согласия всех рабочих с партией.','ir-industry fei-labor1897 revolution','07-033 08-003 08-004')
add('государственная дума','Государственная дума','Представительное учреждение, участвовавшее в законодательстве Российской империи с 1906 года. Депутаты избирались по неравным правилам с ограничениями для разных групп населения. Закону требовалось также одобрение Государственного совета и императора. Современная Дума — другое учреждение в иной конституционной системе.','Первая и Вторая думы были распущены в 1906 и 1907 годах. После изменения избирательных правил 3 июня 1907 года представительство стало выгоднее состоятельным группам.','root-october-archive revolution','08-007 08-023')
add('большевики','Большевики','Течение российской социал-демократии, возникшее при расколе РСДРП в 1903 году и связанное с Лениным. Оно оформилось в отдельную политическую силу. Название восходит к результату одного из голосований съезда и не означает постоянной поддержки большинства населения. После 1917 года партия установила монополию власти.','Осенью 1917 года большевики получили сильные позиции в Петроградском и Московском советах и организовали свержение Временного правительства. На выборах Учредительного собрания они не получили общего большинства голосов.','revolution ohio','08-004 08-015 08-016 08-026')
add('меньшевики','Меньшевики','Течение российской социал-демократии, возникшее при расколе 1903 года. Меньшевики обычно отстаивали более широкую партийную организацию и считали, что социалистическому преобразованию должен предшествовать длительный этап политической свободы и развития хозяйства. Внутри течения существовали серьёзные разногласия, особенно по вопросу войны.','В 1917 году часть меньшевиков поддерживала коалицию социалистов с либералами во Временном правительстве, а меньшевики-интернационалисты критиковали продолжение войны.','warwick revolution','08-004 08-012 08-016')
add('эсеры','Эсеры','Участники Партии социалистов-революционеров, возникшей в начале XX века и опиравшейся на народническую традицию. Главный вопрос их программы — передача земли в пользование трудящихся через общественное регулирование. Партия сочетала массовую политическую работу с деятельностью боевой организации; позднее раскололась на разные течения.','На выборах в Учредительное собрание 1917 года списки эсеров получили наибольшую поддержку. Левые эсеры затем временно участвовали в правительстве вместе с большевиками.','revolution warwick','08-004 08-016 08-026')
add('военный коммунизм','Военный коммунизм','Условное название хозяйственной политики большевистской власти в годы Гражданской войны: расширенная национализация, жёсткое распределение ресурсов, продразвёрстка, ограничения частной торговли и трудовое принуждение. Она отражала и военную чрезвычайность, и представления о переходе к новому строю.','Государство изымало хлеб для армии и городов, что усиливало конфликты с деревней. В 1921 году начался переход к НЭПу, но политическая монополия партии сохранялась.','revolution sov-nep-politics','08-020 08-029 09-002')
add('продразвёрстка','Продразвёрстка','Система обязательной передачи государству установленного количества сельскохозяйственных продуктов. Объём распределяли между территориями и хозяйствами; на практике изъятия часто сопровождались принуждением. Не следует считать, что власти всегда точно определяли и забирали только настоящий «излишек».','В годы Гражданской войны продовольственные отряды изымали хлеб, вызывая сопротивление крестьян. В 1921 году продразвёрстку заменили продналогом, после уплаты которого разрешалось распоряжаться остатком продукции.','revolution sov-nep-politics','08-020 08-029 09-002')
add('гражданская война','Гражданская война','Длительная вооружённая борьба за власть, устройство страны или отделение территории, в которой участвуют крупные силы внутри одного политического пространства. Обычно она включает несколько конфликтов, а не только два лагеря. Иностранное вмешательство может сочетаться с внутренней борьбой.','В России после 1917 года воевали красные и разные белые армии, крестьянские повстанцы и национальные движения. Их программы, союзники и отношения с населением менялись.','revolution ref-denikin ref-kolchak','08-018 08-019 08-029')
add('террор','Террор','Насилие или угроза насилия, используемые для устрашения и подавления политических либо социальных противников. Террор может исходить от государства и негосударственных сил. При изучении нужно установить организаторов, цели, жертв и механизм приказов, а не ограничиваться названием стороны.','Красный и белый террор включали расстрелы, заложничество и преследование групп населения. Различия в организации и масштабе требуют проверки по документам и не снимают ответственности за конкретные преступления.','revolution locarchives','08-028 09-007')
add('пятилетка','Пятилетка','Пятилетний план развития хозяйства и период его выполнения. В СССР планы задавали направления вложений и производственные задания предприятиям. Утверждённая цель, отчёт о выполнении и реальный результат могут различаться: важно проверять качество продукции, ресурсы и способы подсчёта.','Первая советская пятилетка, начавшаяся в 1928 году, отдавала приоритет тяжёлой промышленности. Рост выплавки металла не показывает сам по себе изменение питания и жилья населения.','sov-transformation collective','09-005 09-031')
add('командная экономика','Командная экономика','Способ организации хозяйства, при котором основные решения о производстве, вложениях, снабжении и ценах принимаются административными органами. Предприятия получают обязательные задания и ресурсы по плану. Такая система способна концентрировать средства на выбранных целях, но сталкивается с трудностями информации, стимулов и приспособления к спросу.','В СССР завод мог выполнить план по весу продукции и одновременно выпускать изделия неудобного размера. Этот учебный пример показывает проблему показателей; конкретный случай требует документа.','sov-transformation sov-brezhnev','09-005 09-031 09-039')
add('депортация','Депортация','Принудительное перемещение людей по решению власти с запретом или ограничением возвращения. Основанием может объявляться принадлежность к группе, происхождение или политическое подозрение. Коллективное выселение не доказывает личной вины каждого выселенного и резко отличается от добровольного переселения.','В 1944 году советские власти выселили чеченцев, ингушей и крымских татар. Дорога, потеря имущества и тяжёлые условия спецпоселений приводили к смертям и длительному разрушению привычной жизни.','locarchives sov-transformation','09-044 09-022')
add('холодная война','Холодная война','Длительное противостояние СССР, США и их союзников после Второй мировой войны, включавшее гонку вооружений, идеологическое соперничество и борьбу за влияние. Прямой общей войны между сверхдержавами не произошло, но связанные конфликты уносили жизни в других странах. Точные временные границы зависят от выбранного критерия.','Карибский кризис 1962 года показал риск ядерной войны. Войны в Корее и Афганистане напоминают, что слово «холодная» не означает мирного времени для всего мира.','sov-reconstruction sov-cuba sov-afghanistan','09-024 09-028 09-034')
add('разрядка','Разрядка международной напряжённости','Политика уменьшения риска прямого столкновения между противниками через переговоры, соглашения и связи. Она не требует полного прекращения соперничества. Результат оценивают по конкретным договорам, механизмам контроля и поведению сторон, а не только по дружелюбным заявлениям лидеров.','В 1970-х годах СССР и США подписывали соглашения об ограничении вооружений, одновременно поддерживая разные силы в региональных конфликтах.','sov-brezhnev sov-reform-archive','09-030 09-034 09-035')
add('диссидент','Диссидент','Человек, который открыто не соглашался с официальной идеологией или практикой власти в условиях, где такое несогласие ограничивалось и преследовалось. Советские диссиденты не составляли единого движения с общей программой: среди них были правозащитники, религиозные активисты и сторонники национальной самостоятельности.','Сахаров защищал политических заключённых и право на свободное выражение взглядов. Самиздат помогал распространять тексты, которые не допускались к официальной печати.','ref-sakharov ref-sakharov-memoir ref-solzhenitsyn','09-054 09-037')
add('федерация','Федерация','Государство, состоящее из территориальных частей, полномочия которых установлены общим конституционным порядком. Важно различать юридическое распределение полномочий и реальную самостоятельность регионов. Федерация может существовать при разных политических режимах и не равна союзу полностью независимых государств.','СССР формально состоял из союзных республик, но партийное руководство сильно централизовало решения. Российская Федерация имеет собственный конституционный порядок отношений центра и субъектов.','mod-constitution-original mod-fiscal-federalism sov-nationalities','09-001 10-001 10-019')
add('разделение властей','Разделение властей','Принцип, при котором принятие законов, их исполнение и разрешение споров поручаются разным органам, способным ограничивать друг друга. Цель — затруднить сосредоточение всей власти в одних руках. Разные названия учреждений сами по себе не обеспечивают независимость: нужны работающие полномочия и процедуры.','Проект Сперанского 1809 года разграничивал государственные функции, сохраняя верховенство императора. Конституция 1993 года закрепила разделение законодательной, исполнительной и судебной властей в иной системе.','ir-speransky mod-constitution-original','07-002 10-004 10-005')
add('либерализация цен','Либерализация цен','Сокращение или отмена государственного установления цен, после чего их определяют сделки продавцов и покупателей. Это может уменьшить дефицит, но при нехватке товаров, слабой конкуренции и обесценении денег сопровождается резким ростом расходов. Изменение цен нельзя оценивать отдельно от доходов и сбережений.','В России в январе 1992 года освободили большинство цен. Товары стали доступнее в продаже, но покупательная способность многих семей резко упала.','mod-price-decree imfprices transition','10-002 10-003')
